package com.restrictedcatracker;

public class BossEntry
{
    private String name;
    private int current;
    private int max;

    public BossEntry(String name, int current, int max)
    {
        this.name = name;
        this.current = current;
        this.max = max;
    }

    public String getName()
    {
        return name;
    }

    public void setName(String name)
    {
        this.name = name;
    }

    public int getCurrent()
    {
        return current;
    }

    public void setCurrent(int current)
    {
        this.current = current;
    }

    public int getMax()
    {
        return max;
    }

    public void setMax(int max)
    {
        this.max = max;
    }

    /**
     * A boss counts as complete if:
     *   - max is 0 (boss is entirely unobtainable on this account - there's
     *     nothing to do, so it's done by definition), or
     *   - current has reached the configured achievable max
     */
    public boolean isComplete()
    {
        return max == 0 || current >= max;
    }

    /**
     * Serializes this entry as "Name|current|max"
     */
    public String serialize()
    {
        return name + "|" + current + "|" + max;
    }

    /**
     * Parses an entry from "Name|current|max". Returns null if malformed.
     */
    public static BossEntry parse(String raw)
    {
        if (raw == null || raw.trim().isEmpty())
        {
            return null;
        }

        String[] parts = raw.split("\\|");
        if (parts.length != 3)
        {
            return null;
        }

        try
        {
            String name = parts[0];
            int current = Integer.parseInt(parts[1].trim());
            int max = Integer.parseInt(parts[2].trim());
            return new BossEntry(name, current, max);
        }
        catch (NumberFormatException e)
        {
            return null;
        }
    }
}

package com.restrictedcatracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("restrictedcatracker")
public interface RestrictedCATrackerConfig extends Config
{
    @ConfigItem(
            keyName = "bossData",
            name = "",
            description = "",
            hidden = true
    )
    default String bossData()
    {
        return "";
    }

    @ConfigItem(
            keyName = "bossData",
            name = "",
            description = ""
    )
    void bossData(String data);
}

package com.restrictedcatracker;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.util.ArrayList;
import java.util.List;

public class RestrictedCATrackerPanel extends PluginPanel
{
    private static final Color GREEN = new Color(0, 200, 83);
    private static final Color DEFAULT_TEXT = Color.WHITE;

    private final RestrictedCATrackerConfig config;
    private final List<BossEntry> entries = new ArrayList<>();
    private final JPanel listPanel = new JPanel();

    public RestrictedCATrackerPanel(RestrictedCATrackerConfig config)
    {
        super(false);
        this.config = config;

        setLayout(new BorderLayout());
        setBorder(new EmptyBorder(10, 10, 10, 10));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel title = new JLabel("Restricted CA Tracker");
        title.setForeground(Color.WHITE);
        title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
        title.setBorder(new EmptyBorder(0, 0, 10, 0));

        JButton addButton = new JButton("+ Add Boss");
        addButton.addActionListener(this::onAddBoss);
        addButton.setFocusPainted(false);

        JPanel topPanel = new JPanel(new BorderLayout());
        topPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        topPanel.add(title, BorderLayout.NORTH);
        topPanel.add(addButton, BorderLayout.SOUTH);

        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
        listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JScrollPane scrollPane = new JScrollPane(listPanel);
        scrollPane.setBorder(null);
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);

        add(topPanel, BorderLayout.NORTH);
        add(scrollPane, BorderLayout.CENTER);

        loadFromConfig();
    }

    private void loadFromConfig()
    {
        entries.clear();
        String raw = config.bossData();
        if (raw != null && !raw.trim().isEmpty())
        {
            for (String chunk : raw.split(";;"))
            {
                BossEntry entry = BossEntry.parse(chunk);
                if (entry != null)
                {
                    entries.add(entry);
                }
            }
        }
    }

    private void saveToConfig()
    {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < entries.size(); i++)
        {
            sb.append(entries.get(i).serialize());
            if (i < entries.size() - 1)
            {
                sb.append(";;");
            }
        }
        config.bossData(sb.toString());
    }

    /**
     * Rebuilds the visible list of boss rows from the current entries list.
     * Call this any time entries change or on initial load.
     */
    public void rebuild()
    {
        listPanel.removeAll();

        if (entries.isEmpty())
        {
            JLabel empty = new JLabel("<html><center>No bosses tracked yet.<br>Click '+ Add Boss' to start.</center></html>");
            empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            empty.setHorizontalAlignment(SwingConstants.CENTER);
            empty.setBorder(new EmptyBorder(20, 0, 0, 0));
            listPanel.add(empty);
        }
        else
        {
            for (BossEntry entry : entries)
            {
                listPanel.add(buildRow(entry));
                listPanel.add(Box.createRigidArea(new Dimension(0, 4)));
            }
        }

        listPanel.revalidate();
        listPanel.repaint();
    }

    private JPanel buildRow(BossEntry entry)
    {
        boolean complete = entry.isComplete();

        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(new EmptyBorder(4, 8, 4, 6));

        // Without an explicit max height, BoxLayout (Y_AXIS) on the
        // parent listPanel stretches each row to share the full
        // available vertical space equally - that's what was causing
        // the huge empty rows. Capping preferred/max height fixes it.
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
        row.setPreferredSize(new Dimension(row.getPreferredSize().width, 40));

        JLabel nameLabel = new JLabel(entry.getName());
        nameLabel.setForeground(complete ? GREEN : DEFAULT_TEXT);
        nameLabel.setFont(nameLabel.getFont().deriveFont(Font.BOLD, 14f));

        JLabel progressLabel = new JLabel(entry.getCurrent() + "/" + entry.getMax());
        progressLabel.setForeground(complete ? GREEN : ColorScheme.LIGHT_GRAY_COLOR);
        progressLabel.setFont(progressLabel.getFont().deriveFont(Font.PLAIN, 13f));

        // Vertical box instead of a 2-row grid: grid cells stretch to
        // fill all available height, which was the main cause of the
        // oversized rows. A box only takes as much height as its content
        // actually needs.
        JPanel leftPanel = new JPanel();
        leftPanel.setLayout(new BoxLayout(leftPanel, BoxLayout.Y_AXIS));
        leftPanel.setOpaque(false);
        leftPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
        nameLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        progressLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        leftPanel.add(nameLabel);
        leftPanel.add(progressLabel);

        // Checkmark button — clicking toggles "mark complete" by snapping
        // current up to max (or back down to max-1 if un-checking).
        JButton checkButton = new JButton(complete ? "\u2713" : "\u25CB");
        checkButton.setForeground(complete ? GREEN : ColorScheme.LIGHT_GRAY_COLOR);
        checkButton.setFont(checkButton.getFont().deriveFont(Font.BOLD, 14f));
        checkButton.setBorderPainted(false);
        checkButton.setContentAreaFilled(false);
        checkButton.setFocusPainted(false);
        checkButton.setMargin(new Insets(0, 2, 0, 2));
        checkButton.setToolTipText(complete ? "Mark as not complete" : "Mark as complete (max achievable)");
        checkButton.addActionListener((ActionEvent e) ->
        {
            if (entry.isComplete())
            {
                entry.setCurrent(Math.max(0, entry.getMax() - 1));
            }
            else
            {
                entry.setCurrent(entry.getMax());
            }
            saveToConfig();
            rebuild();
        });

        JButton editButton = new JButton("\u270E");
        editButton.setBorderPainted(false);
        editButton.setContentAreaFilled(false);
        editButton.setFocusPainted(false);
        editButton.setMargin(new Insets(0, 2, 0, 2));
        editButton.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        editButton.setFont(editButton.getFont().deriveFont(12f));
        editButton.setToolTipText("Edit");
        editButton.addActionListener(e -> onEditBoss(entry));

        JButton removeButton = new JButton("\u2715");
        removeButton.setBorderPainted(false);
        removeButton.setContentAreaFilled(false);
        removeButton.setFocusPainted(false);
        removeButton.setMargin(new Insets(0, 2, 0, 2));
        removeButton.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        removeButton.setFont(removeButton.getFont().deriveFont(12f));
        removeButton.setToolTipText("Remove");
        removeButton.addActionListener(e -> onRemoveBoss(entry));

        // FlowLayout sized to content instead of a grid stretching to
        // fill the row - keeps the button cluster compact and centered
        // vertically rather than each button claiming a tall equal cell.
        JPanel buttonPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
        buttonPanel.setOpaque(false);
        buttonPanel.add(checkButton);
        buttonPanel.add(editButton);
        buttonPanel.add(removeButton);

        row.add(leftPanel, BorderLayout.CENTER);
        row.add(buttonPanel, BorderLayout.EAST);

        return row;
    }

    private void onAddBoss(ActionEvent e)
    {
        BossEntry result = showBossDialog("Add Boss", "", 0, 1);
        if (result != null)
        {
            entries.add(result);
            saveToConfig();
            rebuild();
        }
    }

    private void onEditBoss(BossEntry entry)
    {
        BossEntry result = showBossDialog("Edit Boss", entry.getName(), entry.getCurrent(), entry.getMax());
        if (result != null)
        {
            entry.setName(result.getName());
            entry.setCurrent(result.getCurrent());
            entry.setMax(result.getMax());
            saveToConfig();
            rebuild();
        }
    }

    private void onRemoveBoss(BossEntry entry)
    {
        int confirm = JOptionPane.showConfirmDialog(
                this,
                "Remove " + entry.getName() + " from tracker?",
                "Confirm Remove",
                JOptionPane.YES_NO_OPTION
        );

        if (confirm == JOptionPane.YES_OPTION)
        {
            entries.remove(entry);
            saveToConfig();
            rebuild();
        }
    }

    /**
     * Shows a small modal dialog for entering/editing a boss's name,
     * current progress, and your manually-determined achievable max.
     * Returns null if the user cancels or input is invalid.
     */
    private BossEntry showBossDialog(String title, String initialName, int initialCurrent, int initialMax)
    {
        JTextField nameField = new JTextField(initialName);
        JTextField currentField = new JTextField(String.valueOf(initialCurrent));
        JTextField maxField = new JTextField(String.valueOf(initialMax));

        JPanel panel = new JPanel(new GridLayout(3, 2, 5, 8));
        panel.add(new JLabel("Boss name:"));
        panel.add(nameField);
        panel.add(new JLabel("Current completed:"));
        panel.add(currentField);
        panel.add(new JLabel("Max achievable:"));
        panel.add(maxField);

        int result = JOptionPane.showConfirmDialog(
                this,
                panel,
                title,
                JOptionPane.OK_CANCEL_OPTION,
                JOptionPane.PLAIN_MESSAGE
        );

        if (result != JOptionPane.OK_OPTION)
        {
            return null;
        }

        String name = nameField.getText().trim();
        if (name.isEmpty())
        {
            JOptionPane.showMessageDialog(this, "Boss name cannot be empty.");
            return null;
        }

        int current;
        int max;
        try
        {
            current = Integer.parseInt(currentField.getText().trim());
            max = Integer.parseInt(maxField.getText().trim());
        }
        catch (NumberFormatException ex)
        {
            JOptionPane.showMessageDialog(this, "Current and max must be whole numbers.");
            return null;
        }

        if (max < 0)
        {
            JOptionPane.showMessageDialog(this, "Max achievable can't be negative. Use 0 if this boss is fully unobtainable on your account.");
            return null;
        }

        if (current < 0)
        {
            current = 0;
        }

        return new BossEntry(name, current, max);
    }
}

package com.restrictedcatracker;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;

@Slf4j
@PluginDescriptor(
        name = "Restricted CA Tracker",
        description = "Tracks Combat Achievement progress per boss for accounts that can never reach 100% due to account restrictions, marking them complete once your manually-set achievable max is reached.",
        tags = {"combat", "achievements", "restricted", "ironman", "hardcore"}
)
public class RestrictedCATrackerPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private RestrictedCATrackerConfig config;

    private RestrictedCATrackerPanel panel;
    private NavigationButton navButton;

    @Provides
    RestrictedCATrackerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(RestrictedCATrackerConfig.class);
    }

    @Override
    protected void startUp() throws Exception
    {
        panel = new RestrictedCATrackerPanel(config);

        final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");

        navButton = NavigationButton.builder()
                .tooltip("Restricted CA Tracker")
                .icon(icon)
                .priority(5)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);

        SwingUtilities.invokeLater(panel::rebuild);
    }

    @Override
    protected void shutDown() throws Exception
    {
        clientToolbar.removeNavigation(navButton);
        panel = null;
    }

    /**
     * The CA boss-list interface (group 716) lays out each boss's
     * progress text in a flat repeating block of 11 widgets per boss,
     * where the actual "x/y" text lives at offset 1 within each block:
     *   block 0 = decoration, block 1 = "x/y" text, blocks 2-10 = decoration
     * Confirmed via manual widget dump - this is not officially documented
     * by RuneLite, so it could break on a Jagex interface update.
     */
    private static final int CA_GROUP_ID = 716;
    private static final int CA_NAME_WIDGET_RAW_ID = 46923790;
    private static final int CA_PROGRESS_WIDGET_RAW_ID = 46923795;
    private static final int CA_PROGRESS_BLOCK_SIZE = 11;
    private static final int CA_PROGRESS_TEXT_OFFSET = 1;
    // The track/background of the bar sits at offset 2 (width 129, black).
    // The actual fill segments are offsets 7-10 - these start at width 0
    // (or -1) when progress is 0, and presumably grow as tasks complete.
    // We set all of them to the track's full width to render as 100% full.
    private static final int[] CA_PROGRESS_BAR_FILL_OFFSETS = { 7, 8, 9, 10 };
    private static final int GREEN_COLOR = 0x00C853;

    @Subscribe
    public void onGameTick(GameTick event)
    {
        // The CA boss list can be open/closed/re-filtered at any time, so
        // we just re-apply our overrides every tick while it's open. This
        // is cheap (a handful of widget lookups) and self-correcting if
        // Jagex's own UI ever overwrites our text.
        applyOverrides();
    }

    private void applyOverrides()
    {
        Widget container = client.getWidget(CA_GROUP_ID, 0);
        if (container == null)
        {
            // CA boss list isn't open right now.
            return;
        }

        Widget nameWidget = findWidgetById(container, CA_NAME_WIDGET_RAW_ID);
        Widget progressWidget = findWidgetById(container, CA_PROGRESS_WIDGET_RAW_ID);

        if (nameWidget == null || progressWidget == null)
        {
            return;
        }

        Widget[] names = nameWidget.getDynamicChildren();
        Widget[] progress = progressWidget.getDynamicChildren();

        if (names == null || progress == null)
        {
            return;
        }

        Map<String, BossEntry> configuredBosses = loadConfiguredBosses();
        if (configuredBosses.isEmpty())
        {
            return;
        }

        for (int i = 0; i < names.length; i++)
        {
            Widget nameW = names[i];
            if (nameW == null)
            {
                continue;
            }

            String bossName = nameW.getText();
            if (bossName == null || bossName.isEmpty())
            {
                continue;
            }

            BossEntry entry = configuredBosses.get(bossName.toLowerCase());
            if (entry == null)
            {
                continue;
            }

            int progressIndex = i * CA_PROGRESS_BLOCK_SIZE + CA_PROGRESS_TEXT_OFFSET;
            if (progressIndex < 0 || progressIndex >= progress.length)
            {
                continue;
            }

            Widget progressTextWidget = progress[progressIndex];
            if (progressTextWidget == null)
            {
                continue;
            }

            // Always override the displayed text to match your manually
            // entered numbers, regardless of whether they count as
            // "complete" yet. Only the complete case gets the green
            // recolor + filled bar treatment below - an in-progress
            // entry just shows your numbers with the game's normal
            // (untouched) styling.
            String overrideText = entry.getCurrent() + "/" + entry.getMax();
            if (!overrideText.equals(progressTextWidget.getText()))
            {
                progressTextWidget.setText(overrideText);
            }

            if (!entry.isComplete())
            {
                continue;
            }

            progressTextWidget.setTextColor(GREEN_COLOR);

            // Boss name itself also gets recolored green to match the
            // "fully complete" look from a genuinely 100% boss.
            nameW.setTextColor(GREEN_COLOR);

            // Fill the progress bar to match the track's full width and
            // recolor green, so it visually reads as a completed bar
            // instead of an empty/grey one.
            //
            // NOTE: using the track's raw width (offset 2) overshoots the
            // actual bar boundary - the fill segments apparently need to
            // be sized closer to the 4 tier-segment widths (offsets 3-6,
            // ~33px each) rather than the full 129px track. We use the
            // tier segment width here instead and leave a small margin.
            int blockStart = i * CA_PROGRESS_BLOCK_SIZE;
            int tierSegmentWidth = -1;
            int tierOffsetForWidth = 3;
            int tierIndex = blockStart + tierOffsetForWidth;
            if (tierIndex >= 0 && tierIndex < progress.length && progress[tierIndex] != null)
            {
                tierSegmentWidth = progress[tierIndex].getOriginalWidth();
            }

            if (tierSegmentWidth > 0)
            {
                for (int offset : CA_PROGRESS_BAR_FILL_OFFSETS)
                {
                    int fillIndex = blockStart + offset;
                    if (fillIndex < 0 || fillIndex >= progress.length)
                    {
                        continue;
                    }

                    Widget fillWidget = progress[fillIndex];
                    if (fillWidget == null)
                    {
                        continue;
                    }

                    fillWidget.setOriginalWidth(tierSegmentWidth);
                    fillWidget.setTextColor(GREEN_COLOR);
                    fillWidget.setFilled(true);
                    fillWidget.revalidate();
                }
            }
        }
    }

    /**
     * Reads the panel's stored boss config (same source the sidebar panel
     * uses) and returns a lookup by lowercase boss name -> entry. Includes
     * both complete and incomplete entries - incomplete ones still get
     * their text overridden in applyOverrides(), just without the green
     * recolor/bar-fill treatment.
     */
    private Map<String, BossEntry> loadConfiguredBosses()
    {
        Map<String, BossEntry> map = new HashMap<>();
        String raw = config.bossData();
        if (raw == null || raw.trim().isEmpty())
        {
            return map;
        }

        for (String chunk : raw.split(";;"))
        {
            BossEntry entry = BossEntry.parse(chunk);
            if (entry != null)
            {
                map.put(entry.getName().toLowerCase(), entry);
            }
        }

        return map;
    }

    /**
     * Recursively searches a widget tree for a widget matching a specific
     * raw id, checking children/staticChildren/dynamicChildren.
     */
    private Widget findWidgetById(Widget widget, int targetId)
    {
        if (widget == null)
        {
            return null;
        }

        if (widget.getId() == targetId)
        {
            return widget;
        }

        Widget[][] childArrays = { widget.getChildren(), widget.getStaticChildren(), widget.getDynamicChildren() };
        for (Widget[] arr : childArrays)
        {
            if (arr == null)
            {
                continue;
            }
            for (Widget child : arr)
            {
                Widget found = findWidgetById(child, targetId);
                if (found != null)
                {
                    return found;
                }
            }
        }

        return null;
    }
}

package com.restrictedcatracker;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class RestrictedCATrackerTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(RestrictedCATrackerPlugin.class);
        RuneLite.main(args);
    }
}
